using ModelContextProtocol.Server;
using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json.Serialization;

namespace McpServer;

/// <summary>
/// MCP tools are discovered by the SDK via [McpServerToolType] on the class
/// and [McpServerTool] on each method. Constructor parameters are resolved
/// from the DI container automatically.
/// </summary>
[McpServerToolType]
public class WeatherTools
{
    private readonly HttpClient _httpClient;

    // The SDK resolves constructor dependencies from the host's DI container.
    // Here we use a named/typed HttpClient registered via IHttpClientFactory.
    public WeatherTools(HttpClient httpClient)
    {
        _httpClient = httpClient;
    }

    [McpServerTool, Description("Get current weather for a city using the Open-Meteo API.")]
    public async Task<string> GetWeather(
        [Description("Latitude of the location")] double latitude,
        [Description("Longitude of the location")] double longitude)
    {
        var url = $"https://api.open-meteo.com/v1/forecast?latitude={latitude}&longitude={longitude}&current_weather=true";
        var response = await _httpClient.GetFromJsonAsync<WeatherResponse>(url);

        if (response?.CurrentWeather is null)
            return "Unable to fetch weather data.";

        var w = response.CurrentWeather;
        return $"Temperature: {w.Temperature}°C, Wind: {w.WindSpeed} km/h, Direction: {w.WindDirection}°";
    }

    [McpServerTool, Description("Look up geocoding coordinates for a city name.")]
    public async Task<string> GeocodeCityName(
        [Description("City name to look up")] string city)
    {
        var url = $"https://geocoding-api.open-meteo.com/v1/search?name={Uri.EscapeDataString(city)}&count=1";
        var response = await _httpClient.GetFromJsonAsync<GeoResponse>(url);

        if (response?.Results is not { Count: > 0 })
            return $"No results found for '{city}'.";

        var r = response.Results[0];
        return $"{r.Name} ({r.Country}): lat={r.Latitude}, lon={r.Longitude}";
    }
}

// Response models
public class WeatherResponse
{
    [JsonPropertyName("current_weather")]
    public CurrentWeather? CurrentWeather { get; set; }
}

public class CurrentWeather
{
    [JsonPropertyName("temperature")]
    public double Temperature { get; set; }

    [JsonPropertyName("windspeed")]
    public double WindSpeed { get; set; }

    [JsonPropertyName("winddirection")]
    public double WindDirection { get; set; }
}

public class GeoResponse
{
    [JsonPropertyName("results")]
    public List<GeoResult>? Results { get; set; }
}

public class GeoResult
{
    [JsonPropertyName("name")]
    public string Name { get; set; } = "";

    [JsonPropertyName("country")]
    public string Country { get; set; } = "";

    [JsonPropertyName("latitude")]
    public double Latitude { get; set; }

    [JsonPropertyName("longitude")]
    public double Longitude { get; set; }
}

